function meetingNotes(opts){
  opts=opts||{};
  var title=(opts.title||'周会').trim()||'周会';
  var date=(opts.date||'').trim();
  var attendees=String(opts.attendees||'').split(/[\n,，;；、\s]+/).map(function(s){return s.trim();}).filter(Boolean);
  var topics=String(opts.topics||'').split(/[\n,，;；]+/).map(function(s){return s.trim();}).filter(Boolean);
  var L=[];
  L.push('# '+title+' 会议纪要');
  L.push('');
  L.push('- 时间：'+(date||'____'));
  L.push('- 参会：'+(attendees.length?attendees.join('、'):'____'));
  L.push('');
  L.push('## 议题');
  if(topics.length){ for(var i=0;i<topics.length;i++) L.push((i+1)+'. '+topics[i]); }
  else { L.push('1. ____'); }
  L.push('');
  L.push('## 结论');
  L.push('- ');
  L.push('');
  L.push('## 行动项');
  L.push('- [ ] 事项 / 负责人 / 截止');
  return L.join('\n');
}

var EXPORTS={meetingNotes:meetingNotes};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MeetingForgePure = EXPORTS; }
